SELECT l.article_id AS productId, a.title AS productName, COUNT(DISTINCT l.user_id) AS uv FROM author_article_pv_logs l INNER JOIN author_article a ON a.id = l.article_id WHERE l.article_id IN
#{id}
AND l.create_time >= #{startTime}
AND l.create_time <= #{endTime}
AND a.deleted = 0 GROUP BY l.article_id, a.title

